// Robin has hidden goodwill points starting at 0: insults subtract 1, apologies add 1, gifts change nothing; Robin is warm when goodwill is at least 1.
function visible(actions) {
  let goodwill = 0;
  for (const a of actions) {
    if (a === "insult") {
      goodwill -= 1;
    } else if (a === "apologise") {
      goodwill += 1;
    }
    // gift changes nothing
  }
  return goodwill >= 1 ? { mood: "warm" } : { mood: "cold" };
}

// Robin has hidden patience starting at 1: insults always subtract 1, while apologies and gifts add 1 only if patience is still positive; Robin is warm when patience is positive.
function visible(actions) {
  let patience = 1;
  for (const a of actions) {
    if (a === "insult") {
      patience -= 1;
    } else if (a === "apologise" || a === "gift") {
      if (patience > 0) {
        patience += 1;
      }
    }
  }
  return patience > 0 ? { mood: "warm" } : { mood: "cold" };
}

// Robin tracks a hidden grudge count: insults add 1; an apology clears a grudge of at most 1, otherwise just reduces it by 1; gifts do nothing; Robin is warm exactly when the grudge is 0.
function visible(actions) {
  let grudge = 0;
  for (const a of actions) {
    if (a === "insult") {
      grudge += 1;
    } else if (a === "apologise") {
      if (grudge <= 1) {
        grudge = 0;
      } else {
        grudge -= 1;
      }
    }
    // gift does nothing
  }
  return grudge === 0 ? { mood: "warm" } : { mood: "cold" };
}

// Robin's mood is warm initially; insults make it cold; an apology makes it warm unless the two actions just before it were both insults; a gift makes it warm only when the previous action was also a gift.
function visible(actions) {
  let mood = "warm";
  for (let i = 0; i < actions.length; i++) {
    const a = actions[i];
    if (a === "insult") {
      mood = "cold";
    } else if (a === "apologise") {
      const twoInsultsBefore =
        i >= 2 && actions[i - 1] === "insult" && actions[i - 2] === "insult";
      if (!twoInsultsBefore) {
        mood = "warm";
      }
    } else if (a === "gift") {
      if (i >= 1 && actions[i - 1] === "gift") {
        mood = "warm";
      }
    }
  }
  return { mood: mood };
}

